"""Example-driven program synthesis for ARC grids.

A task is solved by finding a short composition of grid primitives (a typed
DSL) that maps every training input to its output. Programs are enumerated
by increasing cost; the first composition consistent with all training
pairs is applied to the test input. The DSL is fixed across all tasks —
nothing about an individual task is hard-coded.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Callable, Dict, List, Optional, Tuple

Grid = List[List[int]]

# --------------------------------------------------------------------------- #
# Grid primitives
# --------------------------------------------------------------------------- #

def _dims(g: Grid):
    return len(g), len(g[0]) if g else 0


def rot90(g: Grid) -> Grid:
    return [list(row) for row in zip(*g[::-1])]


def rot180(g: Grid) -> Grid:
    return [row[::-1] for row in g[::-1]]


def rot270(g: Grid) -> Grid:
    return [list(row) for row in zip(*g)][::-1]


def flip_h(g: Grid) -> Grid:
    return [row[:] for row in g[::-1]]


def flip_v(g: Grid) -> Grid:
    return [row[::-1] for row in g]


def transpose(g: Grid) -> Grid:
    return [list(row) for row in zip(*g)]


def gravity_down(g: Grid) -> Grid:
    """Compact non-zero cells down per column; a uniformly non-zero bottom
    row is treated as an immutable floor."""
    h, w = _dims(g)
    has_floor = w > 0 and h > 1 and all(g[h - 1][c] != 0 for c in range(w))
    last = h - 2 if has_floor else h - 1
    out = [[0] * w for _ in range(h)]
    if has_floor:
        out[h - 1] = g[h - 1][:]
    for c in range(w):
        cells = [g[r][c] for r in range(last + 1) if g[r][c] != 0]
        for i, v in enumerate(cells):
            out[last - i][c] = v
    return out


def fill_enclosed(g: Grid) -> Grid:
    """Recolor background(0) regions unreachable from the border with the
    color of their surrounding wall."""
    h, w = _dims(g)
    reach = [[False] * w for _ in range(h)]
    stack = [(r, c) for r in (0, h - 1) for c in range(w) if g[r][c] == 0]
    stack += [(r, c) for c in (0, w - 1) for r in range(1, h - 1) if g[r][c] == 0]
    while stack:
        r, c = stack.pop()
        if not (0 <= r < h and 0 <= c < w) or reach[r][c] or g[r][c] != 0:
            continue
        reach[r][c] = True
        stack += [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]
    out = [row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if g[r][c] == 0 and not reach[r][c]:
                votes: Dict[int, int] = {}
                for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and g[nr][nc] != 0:
                        votes[nr] = votes.get(nr, 0) + 1
                out[r][c] = max(votes, key=votes.get) if votes else 0
    return out


def remove_non_major(g: Grid) -> Grid:
    """Keep only the most frequent non-background color."""
    counts: Dict[int, int] = {}
    for row in g:
        for v in row:
            if v != 0:
                counts[v] = counts.get(v, 0) + 1
    if not counts:
        return [row[:] for row in g]
    keep = max(counts, key=counts.get)
    return [[v if v == keep else 0 for v in row] for row in g]


def complete_sym_h(g: Grid) -> Grid:
    """Mirror the left half onto the right, OR-ing information from both."""
    h, w = _dims(g)
    out = [row[:] for row in g]
    for r in range(h):
        for c in range(w // 2):
            v = out[r][c] if out[r][c] != 0 else out[r][w - 1 - c]
            out[r][c] = v
            out[r][w - 1 - c] = v
    return out


def complete_sym_v(g: Grid) -> Grid:
    return flip_h(complete_sym_h(flip_h(g)))


def extend_lines_dir(g: Grid, horizontal: bool = True,
                    forward: bool = True) -> Grid:
    """Extend every maximal run of length >=2 in one direction to the edge.
    `horizontal=True, forward=True` -> extend to the right edge, starting at
    each run's leftmost cell (the run origin stays fixed)."""
    h, w = _dims(g)
    out = [row[:] for row in g]
    if horizontal:
        for r in range(h):
            for c in range(w - 1):
                if g[r][c] != 0 and g[r][c] == g[r][c + 1]:
                    is_start = (c == 0 or g[r][c - 1] != g[r][c])
                    if not is_start:
                        continue
                    col = g[r][c]
                    rng = range(c, w) if forward else range(c + 1)
                    for cc in rng:
                        out[r][cc] = col
    else:
        for c in range(w):
            for r in range(h - 1):
                if g[r][c] != 0 and g[r][c] == g[r + 1][c]:
                    is_start = (r == 0 or g[r - 1][c] != g[r][c])
                    if not is_start:
                        continue
                    col = g[r][c]
                    rng = range(r, h) if forward else range(r + 1)
                    for rr in rng:
                        out[rr][c] = col
    return out


def bar_height_to_ruler(g: Grid) -> Grid:
    """Read a single vertical bar's height above the floor and draw a
    matching stack in the leftmost column (counting -> unary encoding)."""
    h, w = _dims(g)
    if h < 3 or w < 3:
        return [row[:] for row in g]
    last_row = [g[h - 1][c] for c in range(w)]
    has_floor = len(set(last_row)) == 1 and last_row[0] != 0
    floor = h - 1 if has_floor else h
    cols = []
    for c in range(1, w):
        cells = [r for r in range(floor) if g[r][c] != 0]
        if cells and cells == list(range(min(cells), floor)):
            cols.append((c, len(cells)))
    if len(cols) != 1:
        return [row[:] for row in g]
    col, n = cols[0]
    color = g[floor - 1][col]
    out = [row[:] for row in g]
    for r in range(h):
        out[r][0] = 0
    for r in range(floor - n, floor):
        out[r][0] = color
    return out


def tile_periodic(g: Grid) -> Grid:
    """Complete a partially-erased periodic tiling: find the smallest
    rectangular period (each side <= 4) consistent with ALL non-zero
    observations and fill zero cells from the inferred motif."""
    h, w = _dims(g)
    best = None
    for ph in range(1, min(4, h) + 1):
        for pw in range(1, min(4, w) + 1):
            if ph == h and pw == w:
                continue
            motif = [[None] * pw for _ in range(ph)]
            ok = True
            for r in range(h):
                for c in range(w):
                    v = g[r][c]
                    if v == 0:
                        continue
                    mr, mc = r % ph, c % pw
                    if motif[mr][mc] is not None and motif[mr][mc] != v:
                        ok = False
                    motif[mr][mc] = v
            if not ok:
                continue
            if not any(motif[mr][mc] is not None
                       for mr in range(ph) for mc in range(pw)):
                continue
            cand = (ph * pw, ph, pw)
            if best is None or cand < best:
                best = cand
    if best is None:
        return [row[:] for row in g]
    _, ph, pw = best
    motif = [[0] * pw for _ in range(ph)]
    for r in range(h):
        for c in range(w):
            if g[r][c] != 0:
                motif[r % ph][c % pw] = g[r][c]
    return [[motif[r % ph][c % pw] for c in range(w)] for r in range(h)]


def _unused():
    return None


def replace_factory(a: int, b: int) -> Callable[[Grid], Grid]:
    def f(g: Grid) -> Grid:
        return [[b if v == a else v for v in row] for row in g]
    f.__name__ = f"replace_{a}_{b}"
    return f


def mask_color_factory(a: int) -> Callable[[Grid], Grid]:
    def f(g: Grid) -> Grid:
        return [[v if v == a else 0 for v in row] for row in g]
    f.__name__ = f"keep_{a}"
    return f


def gravity_towards(dir_: str) -> Callable[[Grid], Grid]:
    def f(g: Grid):
        if dir_ == "up":
            return flip_h(gravity_down(flip_h(g)))
        if dir_ == "left":
            return transpose(gravity_down(transpose(g)))
        if dir_ == "right":
            t = flip_v(transpose(g))
            return transpose(flip_v(gravity_down(t)))
        return gravity_down(g)
    f.__name__ = f"gravity_{dir_}"
    return f


# --------------------------------------------------------------------------- #
# DSL
# --------------------------------------------------------------------------- #

@dataclass(frozen=True)
class Program:
    name: str
    fn: Callable[[Grid], Grid]
    cost: int

    def __call__(self, g: Grid) -> Grid:
        return self.fn(g)


_PRIMITIVES: List[Program] = []
for nm, fn, cost in [
    ("rot90", rot90, 1), ("rot180", rot180, 1), ("rot270", rot270, 1),
    ("flip_h", flip_h, 1), ("flip_v", flip_v, 1), ("transpose", transpose, 1),
    ("gravity_down", gravity_down, 2), ("gravity_up", gravity_towards("up"), 2),
    ("gravity_left", gravity_towards("left"), 2),
    ("gravity_right", gravity_towards("right"), 2),
    ("fill_enclosed", fill_enclosed, 3),
    ("remove_non_major", remove_non_major, 2),
    ("complete_sym_h", complete_sym_h, 2),
    ("complete_sym_v", complete_sym_v, 2),
    ("line_right", lambda g: extend_lines_dir(g, True, True), 2),
    ("line_left", lambda g: extend_lines_dir(g, True, False), 2),
    ("line_down", lambda g: extend_lines_dir(g, False, True), 2),
    ("line_up", lambda g: extend_lines_dir(g, False, False), 2),
    ("bar_height_to_ruler", bar_height_to_ruler, 3),
    ("tile_periodic", tile_periodic, 3),
]:
    _PRIMITIVES.append(Program(nm, fn, cost))

for a in range(10):
    for b in range(10):
        if a != b:
            _PRIMITIVES.append(Program(f"replace_{a}->{b}", replace_factory(a, b), 1))
for a in range(1, 10):
    _PRIMITIVES.append(Program(f"keep_{a}", mask_color_factory(a), 1))

_IDENTITY = Program("identity", lambda g: [row[:] for row in g], 0)


@dataclass
class SynthesisResult:
    program: Optional[Program]
    name: str
    cost: int
    n_candidates: int


def _compose(outer: Program, inner: Program) -> Program:
    return Program(
        f"{outer.name} o {inner.name}",
        lambda g: outer.fn(inner.fn(g)),
        outer.cost + inner.cost,
    )


def _check(p: Program, pairs) -> bool:
    for src, dst in pairs:
        try:
            pred = p(src)
        except Exception:
            return False
        if pred != dst:
            return False
    return True


def synthesize_task(task: dict, max_cost: int = 6,
                    max_nodes: int = 20000) -> SynthesisResult:
    """Cheapest-first (best-first by cost) enumeration of compositions.

    Programs are expanded from the identity; equivalent programs are merged
    by their output signature on the training inputs, so the search stays
    near-linear in the number of *behaviourally distinct* programs."""
    import heapq

    pairs = [(p["input"], p["output"]) for p in task["train"]]
    inputs = [i for i, _ in pairs]

    def sig(prog: Program):
        vals = []
        for g in inputs:
            try:
                vals.append(tuple(tuple(r) for r in prog(g)))
            except Exception:
                return None
        return tuple(vals)

    gold_sig = tuple(tuple(tuple(r) for r in o) for _, o in pairs)
    if sig(_IDENTITY) == gold_sig:
        return SynthesisResult(_IDENTITY, _IDENTITY.name, 0, 1)

    by_cost = sorted(_PRIMITIVES, key=lambda p: (p.cost, p.name))
    heap: List[Tuple[int, int, Program]] = [(0, 0, _IDENTITY)]
    seen_sigs = {sig(_IDENTITY)}
    seen_names = {_IDENTITY.name}
    tested = 1
    counter = 1

    while heap and tested < max_nodes:
        cost, _, inner = heapq.heappop(heap)
        for prim in by_cost:
            new_cost = cost + prim.cost
            if new_cost > max_cost:
                continue
            cand = _compose(prim, inner)
            if cand.name in seen_names:
                continue
            seen_names.add(cand.name)
            signature = sig(cand)
            tested += 1
            if signature is None:
                continue
            if signature == gold_sig:
                return SynthesisResult(cand, cand.name, cand.cost, tested)
            if signature in seen_sigs:
                continue
            seen_sigs.add(signature)
            heapq.heappush(heap, (new_cost, counter, cand))
            counter += 1
            if tested >= max_nodes:
                break
    return SynthesisResult(None, "no_solution", max_cost + 1, tested)


def predict(task: dict, max_cost: int = 6,
            max_nodes: int = 20000) -> Tuple[Optional[Grid], SynthesisResult]:
    res = synthesize_task(task, max_cost=max_cost, max_nodes=max_nodes)
    if res.program is None:
        return None, res
    try:
        return res.program(task["test"][0]["input"]), res
    except Exception:
        return None, res
"""Local evaluator: ARC-style exact-match metrics.

Metrics (mirroring the ARC Prize scoring conventions):
  * task accuracy  = fraction of tasks whose test prediction is exactly correct
  * pixel accuracy = mean fraction of correctly predicted cells
  * coverage       = fraction of tasks for which the synthesizer found a program

The official Kaggle leaderboard scores exact task match with two test-pair
attempts; our held-out local pack uses one test pair per task.
"""
from __future__ import annotations

import argparse
import json
import time
from collections import Counter
from typing import Dict, List, Optional

from .data import Grid, Task, load_benchmark
from .synthesize import predict


def pixel_accuracy(pred: Optional[Grid], gold: Grid) -> float:
    if pred is None:
        return 0.0
    if len(pred) != len(gold) or any(len(a) != len(b) for a, b in zip(pred, gold)):
        return 0.0
    total = sum(len(row) for row in gold)
    correct = sum(a == b for ra, rb in zip(pred, gold) for a, b in zip(ra, rb))
    return correct / total if total else 0.0


def evaluate(tasks: List[Task], max_cost: int = 6,
             max_nodes: int = 20000, limit: int | None = None,
             verbose: bool = True) -> Dict:
    if limit:
        tasks = tasks[:limit]
    n = len(tasks)
    exact = 0
    pix_sum = 0.0
    covered = 0
    costs: Counter = Counter()
    per_family: Dict[str, List[int]] = {}
    per_task = []
    t0 = time.time()

    for t in tasks:
        pred, res = predict(t, max_cost=max_cost, max_nodes=max_nodes)
        gold = t["test"][0]["output"]
        hit = pred == gold
        pa = pixel_accuracy(pred, gold)
        exact += int(hit)
        pix_sum += pa
        covered += int(res.program is not None)
        costs[res.cost if res.program else -1] += 1
        fam = t["id"].split("-")[0]
        per_family.setdefault(fam, [0, 0])
        per_family[fam][1] += 1
        per_family[fam][0] += int(hit)
        per_task.append({"id": t["id"], "exact": hit, "pixel": pa,
                         "program": res.name, "cost": res.cost})

    report = {
        "n_tasks": n,
        "task_accuracy": exact / n if n else 0.0,
        "pixel_accuracy": pix_sum / n if n else 0.0,
        "coverage": covered / n if n else 0.0,
        "elapsed_sec": round(time.time() - t0, 2),
        "cost_histogram": dict(sorted(costs.items())),
        "per_family": {k: {"exact": v[0], "n": v[1],
                           "accuracy": v[0] / v[1]}
                       for k, v in sorted(per_family.items())},
    }
    if verbose:
        print(json.dumps(report, indent=2, ensure_ascii=False))
    return {"summary": report, "per_task": per_task}


def main() -> None:
    ap = argparse.ArgumentParser(description="Local held-out evaluation")
    ap.add_argument("--data", default=None, help="ARC-AGI-2 JSONL directory")
    ap.add_argument("--split", default="evaluation",
                    choices=["training", "evaluation"])
    ap.add_argument("--limit", type=int, default=None)
    ap.add_argument("--max-cost", type=int, default=6)
    ap.add_argument("--max-nodes", type=int, default=20000)
    ap.add_argument("--out", default=None, help="write JSON report here")
    args = ap.parse_args()

    bench = load_benchmark(args.data)
    result = evaluate(bench[args.split], max_cost=args.max_cost,
                      max_nodes=args.max_nodes, limit=args.limit)
    if args.out:
        with open(args.out, "w", encoding="utf-8") as fh:
            json.dump(result, fh, indent=2, ensure_ascii=False)
        print(f"Report written to {args.out}")


if __name__ == "__main__":
    main()
"""Generate a Kaggle submission file for ARC Prize 2026 Paper Track.

Output schema (the competition's `submission.json` / `submission.jsonl`):
    {"id": <task_id>,
     "attempt_1": [[...]], "attempt_2": [[...]]}

Two attempts are produced as required: attempt 1 is the synthesized program;
attempt 2 is a cheaper, distinct hypothesis (lower cost budget); when no
program is found, the test input itself is returned (identity fallback).
"""
from __future__ import annotations

import argparse
import json
import os
from typing import List

from .data import Task, load_benchmark
from .synthesize import predict, synthesize_task


def _identity_attempt(task: Task):
    return task["test"][0]["input"]


def make_predictions(tasks: List[Task], max_cost: int = 6,
                     max_nodes: int = 20000) -> List[dict]:
    rows = []
    for t in tasks:
        pred1, res1 = predict(t, max_cost=max_cost, max_nodes=max_nodes)
        # second attempt: lower-budget, behaviourally distinct search
        res2 = synthesize_task(t, max_cost=max(1, max_cost - 3),
                               max_nodes=max_nodes // 2)
        pred2 = None
        if res2.program is not None and res2.name != res1.name:
            try:
                pred2 = res2.program(t["test"][0]["input"])
            except Exception:
                pred2 = None
        fallback = _identity_attempt(t)
        rows.append({
            "id": t["id"],
            "attempt_1": pred1 if pred1 is not None else fallback,
            "attempt_2": pred2 if pred2 is not None else fallback,
        })
    return rows


def main() -> None:
    ap = argparse.ArgumentParser(description="Build Kaggle submission.json")
    ap.add_argument("--data", default=None)
    ap.add_argument("--split", default="evaluation")
    ap.add_argument("--out", default="submission.json")
    ap.add_argument("--max-cost", type=int, default=6)
    args = ap.parse_args()

    bench = load_benchmark(args.data)
    rows = make_predictions(bench[args.split], max_cost=args.max_cost)
    os.makedirs(os.path.dirname(args.out) or ".", exist_ok=True)
    with open(args.out, "w", encoding="utf-8") as fh:
        json.dump(rows, fh)
    print(f"Wrote {len(rows)} predictions to {args.out}")


if __name__ == "__main__":
    main()
