    ("gravity_down", gravity_down, 2), ("gravity_up", gravity_towards("up"), 2),
    ("gravity_left", gravity_towards("left"), 2),
    ("gravity_right", gravity_towards("right"), 2),
    ("fill_enclosed", fill_enclosed, 3),
    ("remove_non_major", remove_non_major, 2),
    ("complete_sym_h", complete_sym_h, 2),
    ("complete_sym_v", complete_sym_v, 2),
    ("line_right", lambda g: extend_lines_dir(g, True, True), 2),
    ("line_left", lambda g: extend_lines_dir(g, True, False), 2),
    ("line_down", lambda g: extend_lines_dir(g, False, True), 2),
    ("line_up", lambda g: extend_lines_dir(g, False, False), 2),
    ("bar_height_to_ruler", bar_height_to_ruler, 3),
    ("tile_periodic", tile_periodic, 3),
]:
