            _PRIMITIVES.append(Program(f"replace_{a}->{b}", replace_factory(a, b), 1))
for a in range(1, 10):
    _PRIMITIVES.append(Program(f"keep_{a}", mask_color_factory(a), 1))

_IDENTITY = Program("identity", lambda g: [row[:] for row in g], 0)


@dataclass
class SynthesisResult:
    program: Optional[Program]
    name: str
    cost: int
    n_candidates: int


def _compose(outer: Program, inner: Program) -> Program:
    return Program(
        f"{outer.name} o {inner.name}",
        lambda g: outer.fn(inner.fn(g)),
        outer.cost + inner.cost,
    )


def _check(p: Program, pairs) -> bool:
    for src, dst in pairs:
        try:
            pred = p(src)
        except Exception:
            return False
        if pred != dst:
            return False
    return True


def synthesize_task(task: dict, max_cost: int = 6,
                    max_nodes: int = 20000) -> SynthesisResult:
    """Cheapest-first (best-first by cost) enumeration of compositions.

    Programs are expanded from the identity; equivalent programs are merged
    by their output signature on the training inputs, so the search stays
    near-linear in the number of *behaviourally distinct* programs."""
    import heapq

    pairs = [(p["input"], p["output"]) for p in task["train"]]
    inputs = [i for i, _ in pairs]

    def sig(prog: Program):
        vals = []
        for g in inputs:
            try:
                vals.append(tuple(tuple(r) for r in prog(g)))
            except Exception:
                return None
        return tuple(vals)

    gold_sig = tuple(tuple(tuple(r) for r in o) for _, o in pairs)
    if sig(_IDENTITY) == gold_sig:
        return SynthesisResult(_IDENTITY, _IDENTITY.name, 0, 1)

    by_cost = sorted(_PRIMITIVES, key=lambda p: (p.cost, p.name))
    heap: List[Tuple[int, int, Program]] = [(0, 0, _IDENTITY)]
    seen_sigs = {sig(_IDENTITY)}
    seen_names = {_IDENTITY.name}
    tested = 1
    counter = 1

    while heap and tested < max_nodes:
        cost, _, inner = heapq.heappop(heap)
        for prim in by_cost:
            new_cost = cost + prim.cost
            if new_cost > max_cost:
                continue
            cand = _compose(prim, inner)
            if cand.name in seen_names:
                continue
            seen_names.add(cand.name)
            signature = sig(cand)
            tested += 1
            if signature is None:
                continue
            if signature == gold_sig:
                return SynthesisResult(cand, cand.name, cand.cost, tested)
            if signature in seen_sigs:
                continue
            seen_sigs.add(signature)
            heapq.heappush(heap, (new_cost, counter, cand))
            counter += 1
            if tested >= max_nodes:
                break
    return SynthesisResult(None, "no_solution", max_cost + 1, tested)


def predict(task: dict, max_cost: int = 6,
            max_nodes: int = 20000) -> Tuple[Optional[Grid], SynthesisResult]:
    res = synthesize_task(task, max_cost=max_cost, max_nodes=max_nodes)
    if res.program is None:
        return None, res
    try:
        return res.program(task["test"][0]["input"]), res
    except Exception:
        return None, res
"""Local evaluator: ARC-style exact-match metrics.

Metrics (mirroring the ARC Prize scoring conventions):
  * task accuracy  = fraction of tasks whose test prediction is exactly correct
  * pixel accuracy = mean fraction of correctly predicted cells
  * coverage       = fraction of tasks for which the synthesizer found a program

The official Kaggle leaderboard scores exact task match with two test-pair
attempts; our held-out local pack uses one test pair per task.
"""
from __future__ import annotations

import argparse
import json
import time
from collections import Counter
from typing import Dict, List, Optional

from .data import Grid, Task, load_benchmark
from .synthesize import predict


def pixel_accuracy(pred: Optional[Grid], gold: Grid) -> float:
    if pred is None:
        return 0.0
    if len(pred) != len(gold) or any(len(a) != len(b) for a, b in zip(pred, gold)):
        return 0.0
    total = sum(len(row) for row in gold)
    correct = sum(a == b for ra, rb in zip(pred, gold) for a, b in zip(ra, rb))
    return correct / total if total else 0.0


def evaluate(tasks: List[Task], max_cost: int = 6,
             max_nodes: int = 20000, limit: int | None = None,
             verbose: bool = True) -> Dict:
    if limit:
        tasks = tasks[:limit]
    n = len(tasks)
    exact = 0
    pix_sum = 0.0
    covered = 0
    costs: Counter = Counter()
    per_family: Dict[str, List[int]] = {}
    per_task = []
    t0 = time.time()

    for t in tasks:
        pred, res = predict(t, max_cost=max_cost, max_nodes=max_nodes)
        gold = t["test"][0]["output"]
        hit = pred == gold
        pa = pixel_accuracy(pred, gold)
        exact += int(hit)
        pix_sum += pa
        covered += int(res.program is not None)
        costs[res.cost if res.program else -1] += 1
        fam = t["id"].split("-")[0]
        per_family.setdefault(fam, [0, 0])
        per_family[fam][1] += 1
        per_family[fam][0] += int(hit)
        per_task.append({"id": t["id"], "exact": hit, "pixel": pa,
                         "program": res.name, "cost": res.cost})

    report = {
        "n_tasks": n,
        "task_accuracy": exact / n if n else 0.0,
        "pixel_accuracy": pix_sum / n if n else 0.0,
        "coverage": covered / n if n else 0.0,
        "elapsed_sec": round(time.time() - t0, 2),
        "cost_histogram": dict(sorted(costs.items())),
        "per_family": {k: {"exact": v[0], "n": v[1],
                           "accuracy": v[0] / v[1]}
                       for k, v in sorted(per_family.items())},
    }
    if verbose:
        print(json.dumps(report, indent=2, ensure_ascii=False))
    return {"summary": report, "per_task": per_task}


def main() -> None:
    ap = argparse.ArgumentParser(description="Local held-out evaluation")
    ap.add_argument("--data", default=None, help="ARC-AGI-2 JSONL directory")
    ap.add_argument("--split", default="evaluation",
                    choices=["training", "evaluation"])
    ap.add_argument("--limit", type=int, default=None)
    ap.add_argument("--max-cost", type=int, default=6)
    ap.add_argument("--max-nodes", type=int, default=20000)
    ap.add_argument("--out", default=None, help="write JSON report here")
    args = ap.parse_args()

    bench = load_benchmark(args.data)
    result = evaluate(bench[args.split], max_cost=args.max_cost,
                      max_nodes=args.max_nodes, limit=args.limit)
    if args.out:
        with open(args.out, "w", encoding="utf-8") as fh:
            json.dump(result, fh, indent=2, ensure_ascii=False)
        print(f"Report written to {args.out}")


if __name__ == "__main__":
    main()
"""Generate a Kaggle submission file for ARC Prize 2026 Paper Track.

Output schema (the competition's `submission.json` / `submission.jsonl`):
    {"id": <task_id>,
     "attempt_1": [[...]], "attempt_2": [[...]]}

Two attempts are produced as required: attempt 1 is the synthesized program;
attempt 2 is a cheaper, distinct hypothesis (lower cost budget); when no
program is found, the test input itself is returned (identity fallback).
"""
from __future__ import annotations

import argparse
import json
import os
from typing import List

from .data import Task, load_benchmark
from .synthesize import predict, synthesize_task


def _identity_attempt(task: Task):
    return task["test"][0]["input"]


def make_predictions(tasks: List[Task], max_cost: int = 6,
                     max_nodes: int = 20000) -> List[dict]:
    rows = []
    for t in tasks:
        pred1, res1 = predict(t, max_cost=max_cost, max_nodes=max_nodes)
        # second attempt: lower-budget, behaviourally distinct search
        res2 = synthesize_task(t, max_cost=max(1, max_cost - 3),
                               max_nodes=max_nodes // 2)
        pred2 = None
        if res2.program is not None and res2.name != res1.name:
            try:
                pred2 = res2.program(t["test"][0]["input"])
            except Exception:
                pred2 = None
        fallback = _identity_attempt(t)
        rows.append({
            "id": t["id"],
            "attempt_1": pred1 if pred1 is not None else fallback,
            "attempt_2": pred2 if pred2 is not None else fallback,
        })
    return rows


def main() -> None:
    ap = argparse.ArgumentParser(description="Build Kaggle submission.json")
    ap.add_argument("--data", default=None)
    ap.add_argument("--split", default="evaluation")
    ap.add_argument("--out", default="submission.json")
    ap.add_argument("--max-cost", type=int, default=6)
    args = ap.parse_args()

    bench = load_benchmark(args.data)
    rows = make_predictions(bench[args.split], max_cost=args.max_cost)
    os.makedirs(os.path.dirname(args.out) or ".", exist_ok=True)
    with open(args.out, "w", encoding="utf-8") as fh:
        json.dump(rows, fh)
    print(f"Wrote {len(rows)} predictions to {args.out}")


if __name__ == "__main__":
    main()
