"""Grid primitives for the ARC solver (pure Python, no dependencies).

Every primitive is a total function Grid -> Grid. Primitives are written to
be *safe*: on inputs where the underlying assumption does not hold they
return a best-effort grid instead of raising, so compositions never crash
the search.
"""
from __future__ import annotations

from typing import Dict, List

Grid = List[List[int]]


def dims(g: Grid):
    return len(g), len(g[0]) if g else 0


# --- rigid transforms -------------------------------------------------------
def rot90(g: Grid) -> Grid:
    return [list(row) for row in zip(*g[::-1])]


def rot180(g: Grid) -> Grid:
    return [row[::-1] for row in g[::-1]]


def rot270(g: Grid) -> Grid:
    return [list(row) for row in zip(*g)][::-1]


def flip_h(g: Grid) -> Grid:
    return [row[:] for row in g[::-1]]


def flip_v(g: Grid) -> Grid:
    return [row[::-1] for row in g]


def transpose(g: Grid) -> Grid:
    return [list(row) for row in zip(*g)]


# --- physics-like ------------------------------------------------------------
def gravity_down(g: Grid) -> Grid:
    """Pack non-zero cells to the bottom of each column. A fully non-zero
    bottom row is treated as a fixed floor."""
    h, w = dims(g)
    if h == 0 or w == 0:
        return [row[:] for row in g]
    floor = h > 1 and all(g[h - 1][c] != 0 for c in range(w))
    last = h - 2 if floor else h - 1
    out = [[0] * w for _ in range(h)]
    if floor:
        out[h - 1] = g[h - 1][:]
    for c in range(w):
        cells = [g[r][c] for r in range(last + 1) if g[r][c] != 0]
        for i, v in enumerate(cells):
            out[last - i][c] = v
    return out


def gravity_up(g: Grid) -> Grid:
    return flip_h(gravity_down(flip_h(g)))


def gravity_left(g: Grid) -> Grid:
    return transpose(gravity_down(transpose(g)))


def gravity_right(g: Grid) -> Grid:
    return flip_v(transpose(gravity_down(transpose(flip_v(g)))))


# --- region / color ----------------------------------------------------------
def fill_enclosed(g: Grid) -> Grid:
    """Flood-fill background (0) cells unreachable from the border with the
    majority non-zero color adjacent to the enclosed region."""
    h, w = dims(g)
    reach = [[False] * w for _ in range(h)]
    stack = [(r, c) for r in (0, h - 1) for c in range(w) if g[r][c] == 0]
    stack += [(r, c) for c in (0, w - 1) for r in range(1, h - 1) if g[r][c] == 0]
    while stack:
        r, c = stack.pop()
        if not (0 <= r < h and 0 <= c < w) or reach[r][c] or g[r][c] != 0:
            continue
        reach[r][c] = True
        stack += [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]
    out = [row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if g[r][c] == 0 and not reach[r][c]:
                votes: Dict[int, int] = {}
                for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and g[nr][nc] != 0:
                        votes[g[nr][nc]] = votes.get(g[nr][nc], 0) + 1
                out[r][c] = max(votes, key=votes.get) if votes else 0
