def keep_majority_color(g: Grid) -> Grid:
    """Zero out everything except the most frequent non-background color."""
    counts: Dict[int, int] = {}
    for row in g:
        for v in row:
            if v != 0:
                counts[v] = counts.get(v, 0) + 1
    if not counts:
