IDENTITY = Program("identity", lambda g: [row[:] for row in g], 0)


@dataclass
class SynthesisResult:
    program: Optional[Program]
    name: str
    cost: int
    n_tested: int


def _compose(outer: Program, inner: Program) -> Program:
    return Program(f"{outer.name} . {inner.name}",
                   lambda g: outer.fn(inner.fn(g)),
                   outer.cost + inner.cost)


def _signature(prog: Program, inputs: List[Grid]):
    vals = []
    for g in inputs:
        try:
            vals.append(tuple(tuple(r) for r in prog(g)))
        except Exception:
            return None
    return tuple(vals)


def synthesize(task: dict, max_cost: int = 6, max_nodes: int = 20000) -> SynthesisResult:
    pairs = [(p["input"], p["output"]) for p in task["train"]]
    inputs = [i for i, _ in pairs]
    gold = tuple(tuple(tuple(r) for r in o) for _, o in pairs)

    if _signature(IDENTITY, inputs) == gold:
        return SynthesisResult(IDENTITY, IDENTITY.name, 0, 1)

    heap: List[Tuple[int, int, Program]] = [(0, 0, IDENTITY)]
    seen_sigs = {_signature(IDENTITY, inputs)}
    seen_names = {IDENTITY.name}
    tested, counter = 1, 1

    while heap and tested < max_nodes:
        cost, _, inner = heapq.heappop(heap)
        for prim in PRIMITIVES:
            new_cost = cost + prim.cost
            if new_cost > max_cost:
                continue
            cand = _compose(prim, inner)
            if cand.name in seen_names:
                continue
            seen_names.add(cand.name)
            sig = _signature(cand, inputs)
            tested += 1
            if sig is None:
                continue
            if sig == gold:
                return SynthesisResult(cand, cand.name, cand.cost, tested)
            if sig not in seen_sigs:
                seen_sigs.add(sig)
                heapq.heappush(heap, (new_cost, counter, cand))
                counter += 1
            if tested >= max_nodes:
                break
    return SynthesisResult(None, "no_solution", max_cost + 1, tested)


def predict(task: dict, max_cost: int = 6, max_nodes: int = 20000):
    """Return (predicted grid or None, SynthesisResult)."""
    res = synthesize(task, max_cost=max_cost, max_nodes=max_nodes)
    if res.program is None:
        return None, res
    try:
        return res.program(task["test"][0]["input"]), res
    except Exception:
        return None, res
