        out = [[motif[r % th][c % tw] for c in range(w)] for r in range(h)]
        pairs.append((g, out))
    return _pack("tile", rng, pairs)


def gen_line(rng):
    h, w = rng.randint(8, 13), rng.randint(8, 13)
    color = rng.randint(1, 9)

    def make():
        g = _grid(h, w)
        r = rng.randrange(h)
        c0 = rng.randrange(w - 3)
        n = rng.randint(2, 3)
        for c in range(c0, c0 + n):
            g[r][c] = color
        out = [row[:] for row in g]
        for c in range(c0 + n, w):
            out[r][c] = color
        return g, out

    return _pack("line", rng, [make() for _ in range(4)])


_FAMILIES = [gen_recolor, gen_rotate, gen_flip, gen_gravity, gen_denoise,
             gen_fill_enclosed, gen_symmetry, gen_count, gen_tile, gen_line]


def generate_pack(n: int = 200, seed: int = 20261001) -> List[Task]:
    rng = random.Random(seed)
    tasks = [_FAMILIES[i % len(_FAMILIES)](rng) for i in range(n)]
    rng.shuffle(tasks)
    return tasks


def write_pack(path: str, tasks) -> None:
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    with open(path, "w", encoding="utf-8") as fh:
        for t in tasks:
            fh.write(json.dumps(t) + "\n")


if __name__ == "__main__":
    import argparse

    ap = argparse.ArgumentParser(description="Generate the local ARC-AGI-2-format pack")
    ap.add_argument("--out", default="data/local_pack")
    ap.add_argument("--n", type=int, default=200)
    args = ap.parse_args()
    os.makedirs(args.out, exist_ok=True)
    write_pack(os.path.join(args.out, "training.jsonl"), generate_pack(args.n, 20261001))
    write_pack(os.path.join(args.out, "evaluation.jsonl"), generate_pack(args.n, 20261002))
    print(f"Wrote {args.n} tasks per split to {args.out}")
