"""Task IO plus a deterministic local benchmark pack in ARC-AGI-2 JSONL format.

Task format (identical to the official ARC-AGI-2 JSONL):
    {"id": str, "train": [{"input": [[int]], "output": [[int]]}],
     "test":  [{"input": [[int]], "output": [[int]]}]}

If the official ARC-AGI-2 data directory is found (locally or on Kaggle),
it is used directly; otherwise a procedurally generated pack with the same
schema is produced so the whole pipeline runs fully offline.
"""
from __future__ import annotations

import json
import os
import random
from typing import Dict, List, Tuple

Grid = List[List[int]]
Task = Dict

OFFICIAL_CANDIDATES = [
    "data/ARC-AGI-2",
    "/kaggle/input/arc-agi-2-data/ARC-AGI-2",
    "/kaggle/input/arc-prize-2026",
]


def _read_jsonl(path: str) -> List[Task]:
    with open(path, "r", encoding="utf-8") as fh:
        return [json.loads(line) for line in fh if line.strip()]


def load_benchmark(data_dir: str | None = None) -> Dict[str, List[Task]]:
    candidates = [data_dir] if data_dir else []
    candidates += OFFICIAL_CANDIDATES
    for base in candidates:
        if base and os.path.exists(os.path.join(base, "training.jsonl")):
            return {
                "training": _read_jsonl(os.path.join(base, "training.jsonl")),
                "evaluation": _read_jsonl(os.path.join(base, "evaluation.jsonl")),
            }
    return {
        "training": generate_pack(200, 20261001),
        "evaluation": generate_pack(200, 20261002),
    }


# --------------------------------------------------------------------------- #
# Deterministic synthetic pack (ARC-AGI-2 schema)
# --------------------------------------------------------------------------- #
def _grid(h, w, rng=None, noise=0.0) -> Grid:
    g = [[0] * w for _ in range(h)]
    if rng and noise:
        for r in range(h):
            for c in range(w):
                if rng.random() < noise:
                    g[r][c] = rng.randint(0, 9)
    return g


def _pack(name, rng, pairs: List[Tuple[Grid, Grid]]) -> Task:
    return {"id": f"{name}-{rng.randrange(1 << 24):06x}",
            "train": [{"input": i, "output": o} for i, o in pairs[:3]],
            "test": [{"input": pairs[3][0], "output": pairs[3][1]}]}


def gen_recolor(rng):
    h, w = rng.randint(5, 12), rng.randint(5, 12)
    a, b = rng.sample(range(1, 10), 2)
    pairs = []
    for _ in range(4):
        g = _grid(h, w, rng, 0.5)
        pairs.append((g, [[b if x == a else x for x in row] for row in g]))
    return _pack("recolor", rng, pairs)


def gen_rotate(rng):
    h, w = rng.randint(5, 11), rng.randint(5, 11)
    k = rng.choice([1, 2, 3])
    pairs = []
    for _ in range(4):
        g = _grid(h, w, rng, 0.55)
        out = g
        for _ in range(k):
            out = [list(row) for row in zip(*out[::-1])]
        pairs.append((g, out))
    return _pack("rot", rng, pairs)


def gen_flip(rng):
    axis = rng.choice(["h", "v"])
    h, w = rng.randint(5, 12), rng.randint(5, 12)
    pairs = []
    for _ in range(4):
        g = _grid(h, w, rng, 0.55)
        out = g[::-1] if axis == "h" else [row[::-1] for row in g]
        pairs.append((g, [row[:] for row in out]))
    return _pack("flip", rng, pairs)


def gen_gravity(rng):
    h, w = rng.randint(7, 12), rng.randint(5, 10)
    color = rng.randint(1, 9)

    def make():
        g = _grid(h, w)
        n = rng.randint(4, h * w // 3)
        for r, c in rng.sample([(r, c) for r in range(h - 1) for c in range(w)], n):
            g[r][c] = color
        out = [[0] * w for _ in range(h)]
        for c in range(w):
            k = sum(1 for r in range(h - 1) if g[r][c] == color)
            for r in range(h - 2, h - 2 - k, -1):
                out[r][c] = color
        g[h - 1] = [color] * w
        out[h - 1] = [color] * w
        return g, out

    return _pack("gravity", rng, [make() for _ in range(4)])


def gen_denoise(rng):
    h, w = rng.randint(7, 13), rng.randint(7, 13)
    color = rng.randint(1, 9)

    def make():
        g = _grid(h, w)
        s = rng.randint(3, 5)
        r0, c0 = rng.randint(0, h - s), rng.randint(0, w - s)
        for r in range(r0, r0 + s):
            for c in range(c0, c0 + s):
                g[r][c] = color
        g[r0 + s // 2][c0 + s // 2] = 0
        for _ in range(rng.randint(3, 8)):
            r, c = rng.randrange(h), rng.randrange(w)
            if g[r][c] == 0:
                g[r][c] = rng.choice([c2 for c2 in range(1, 10) if c2 != color])
        return g, [[x if x == color else 0 for x in row] for row in g]

    return _pack("denoise", rng, [make() for _ in range(4)])


def gen_fill_enclosed(rng):
    h, w = rng.randint(7, 12), rng.randint(7, 12)
    wall = rng.randint(1, 9)
    fill = rng.choice([c for c in range(1, 10) if c != wall])

    def make():
        g = _grid(h, w)
        rh, rw = rng.randint(3, 4), rng.randint(3, 5)
        r0, c0 = rng.randint(1, h - rh - 1), rng.randint(1, w - rw - 1)
        for c in range(c0, c0 + rw):
            g[r0][c] = wall
            g[r0 + rh - 1][c] = wall
        for r in range(r0, r0 + rh):
            g[r][c0] = wall
            g[r][c0 + rw - 1] = wall
        for r in range(r0 + 1, r0 + rh - 1):
            for c in range(c0 + 1, c0 + rw - 1):
                g[r][c] = fill
        return g

    pairs = []
    for _ in range(4):
        g = make()
        out = [row[:] for row in g]
        # erase interior, then refilled via enclosed mask
        reach = [[False] * w for _ in range(h)]
        stack = [(r, c) for r in (0, h - 1) for c in range(w) if g[r][c] == 0]
        stack += [(r, c) for c in (0, w - 1) for r in range(1, h - 1) if g[r][c] == 0]
        while stack:
            r, c = stack.pop()
            if not (0 <= r < h and 0 <= c < w) or reach[r][c] or g[r][c] != 0:
                continue
            reach[r][c] = True
            stack += [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]
        inp = [[g[r][c] if (g[r][c] != fill or reach[r][c]) else 0
                for c in range(w)] for r in range(h)]
        pairs.append((inp, out))
    return _pack("fill", rng, pairs)


def gen_symmetry(rng):
    h = w = rng.randint(7, 12)
    pairs = []
    for _ in range(4):
        g = _grid(h, w, rng, 0.25)
        for r in range(h):
            for c in range(w // 2):
                g[r][w - 1 - c] = g[r][c]
        inp = [row[:] for row in g]
        for r in range(h):
            for c in range(w // 2):
                if rng.random() < 0.4:
                    inp[r][w - 1 - c] = 0
        out = [row[:] for row in inp]
        for r in range(h):
            for c in range(w // 2):
                out[r][w - 1 - c] = inp[r][c]
        pairs.append((inp, out))
    return _pack("sym", rng, pairs)


def gen_count(rng):
    h, w = rng.randint(7, 11), rng.randint(7, 11)
    color = rng.randint(1, 9)

    def make():
        g = _grid(h, w)
        col = rng.randrange(1, w - 1)
        n = rng.randint(1, h - 2)
        for r in range(h - n, h):
            g[r][col] = color
        out = [row[:] for row in g]
        for r in range(h):
            out[r][0] = color if r >= h - n else 0
        return g, out

    return _pack("count", rng, [make() for _ in range(4)])


def gen_tile(rng):
    th, tw = rng.randint(2, 3), rng.randint(2, 3)
    h, w = th * rng.randint(2, 3), tw * rng.randint(2, 3)
    motif = _grid(th, tw, rng, 0.8)
    pairs = []
    for _ in range(4):
        g = [[motif[r % th][c % tw] if rng.random() > 0.35 else 0
              for c in range(w)] for r in range(h)]
        out = [[motif[r % th][c % tw] for c in range(w)] for r in range(h)]
        pairs.append((g, out))
    return _pack("tile", rng, pairs)


def gen_line(rng):
    h, w = rng.randint(8, 13), rng.randint(8, 13)
    color = rng.randint(1, 9)

    def make():
        g = _grid(h, w)
        r = rng.randrange(h)
        c0 = rng.randrange(w - 3)
        n = rng.randint(2, 3)
        for c in range(c0, c0 + n):
            g[r][c] = color
        out = [row[:] for row in g]
        for c in range(c0 + n, w):
            out[r][c] = color
        return g, out

    return _pack("line", rng, [make() for _ in range(4)])


_FAMILIES = [gen_recolor, gen_rotate, gen_flip, gen_gravity, gen_denoise,
             gen_fill_enclosed, gen_symmetry, gen_count, gen_tile, gen_line]


def generate_pack(n: int = 200, seed: int = 20261001) -> List[Task]:
    rng = random.Random(seed)
    tasks = [_FAMILIES[i % len(_FAMILIES)](rng) for i in range(n)]
    rng.shuffle(tasks)
    return tasks


def write_pack(path: str, tasks) -> None:
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    with open(path, "w", encoding="utf-8") as fh:
        for t in tasks:
            fh.write(json.dumps(t) + "\n")


if __name__ == "__main__":
    import argparse

    ap = argparse.ArgumentParser(description="Generate the local ARC-AGI-2-format pack")
    ap.add_argument("--out", default="data/local_pack")
    ap.add_argument("--n", type=int, default=200)
    args = ap.parse_args()
    os.makedirs(args.out, exist_ok=True)
    write_pack(os.path.join(args.out, "training.jsonl"), generate_pack(args.n, 20261001))
    write_pack(os.path.join(args.out, "evaluation.jsonl"), generate_pack(args.n, 20261002))
    print(f"Wrote {args.n} tasks per split to {args.out}")
